package com.biocircular.compostaje.entity;
import jakarta.persistence.*; import java.time.OffsetDateTime; import java.util.UUID;
@Entity @Table(name="lote_etapa") public class LoteEtapa { @Id @GeneratedValue private UUID id; @ManyToOne @JoinColumn(name="lote_id") private Lote lote; @ManyToOne @JoinColumn(name="etapa_id") private EtapaCompostaje etapa; @Column(name="fecha_inicio") private OffsetDateTime fechaInicio; @Column(name="fecha_fin") private OffsetDateTime fechaFin; @Enumerated(EnumType.STRING) private EstadoEtapa estado=EstadoEtapa.EN_PROCESO; @Column(name="responsable_usuario_externo_id") private UUID responsableId; public UUID getId(){return id;} public Lote getLote(){return lote;} public EtapaCompostaje getEtapa(){return etapa;} public OffsetDateTime getFechaInicio(){return fechaInicio;} public OffsetDateTime getFechaFin(){return fechaFin;} public EstadoEtapa getEstado(){return estado;} public UUID getResponsableId(){return responsableId;} public void iniciar(Lote l,EtapaCompostaje e,UUID r){lote=l;etapa=e;responsableId=r;fechaInicio=OffsetDateTime.now();} public void finalizar(){estado=EstadoEtapa.FINALIZADA;fechaFin=OffsetDateTime.now();} }
